<?php if (!isset($accessRows) || !user_has_role('ADMIN')) { http_response_code(403); exit; } ?>
<div class="page-heading"><div><p class="eyebrow">ADMINISTRACIÓN</p><h1><?= $accessRow === null ? 'Solicitudes de acceso' : 'Revisar solicitud' ?></h1><p class="page-description">El acceso se concede únicamente después de tu aprobación y del establecimiento de contraseña.</p></div></div>
<?php if ($accessError !== null): ?><div class="notice notice-error" role="alert"><?= e($accessError) ?></div><?php endif; ?>
<?php if ($accessRow === null): ?>
